mapper.select:
SELECT c.id, c.school_id, s.school_name, c.class_name, c.class_code, c.grade_id, g.grade_name, c.head_teacher_id, u.teacher_name AS head_teacher_name, c.enrollment_year, c.graduation_year, c.create_time, t.id AS termId, t.term_name FROM t_educl_class c LEFT JOIN t_educl_term t ON t.id = c.term_id and t.is_valid = 1 LEFT JOIN t_school_manage s ON s.id = c.school_id LEFT JOIN t_educl_grade g ON g.id = c.grade_id LEFT JOIN t_as_teacher u ON u.id = c.head_teacher_id
c.is_valid = 1
AND c.class_name LIKE concat('%', #{query.className}, '%')
AND c.school_id = #{query.schoolId}
AND c.grade_id IN
#{gradeId}
AND c.head_teacher_id = #{query.headTeacherId}
AND c.term_id = #{query.termId}
AND c.create_time BETWEEN #{query.createTimeStart} AND #{query.createTimeEnd}
ORDER BY c.create_time DESC

SELECT DISTINCT t.user_id FROM t_as_course_class cc INNER JOIN t_as_course_category cg on cg.id = cc.category_id and cg.is_valid = 1 INNER JOIN t_as_student_destination sd on sd.course_class_id = cc.id and sd.is_valid = 1 INNER JOIN t_as_student stu on stu.id = sd.student_id and stu.register_status = 1 and stu.is_valid = 1 INNER JOIN t_educl_class c on c.id = stu.class_id and c.is_valid = 1 INNER JOIN t_as_teacher t on t.id = c.head_teacher_id and t.is_valid = 1 and t.user_id is not null WHERE cc.is_valid = 1
AND cg.id IN
#{categoryId}
AND cc.id IN
#{courseClassId}

SELECT stu.id AS studentId, gs.guardian_user_id AS userId FROM t_educl_class c INNER JOIN t_as_student stu ON stu.class_id = c.id and stu.register_status = 1 and stu.is_valid = 1 INNER JOIN t_as_guardian_student gs on gs.student_identity_id = stu.student_identity_id and gs.is_valid = 1 and bind_status = 1 WHERE c.is_valid = 1 and c.school_id = #{schoolId} and gs.guardian_user_id is not NULL AND stu.term_id = #{termId} AND c.id IN
#{classId}
AND stu.id IN
#{studentId}
